// Independent fixture: compress original generated bytes with public Zstd API.
#include "native_asset_decode.hpp"
#include "native_asset_singleflight.hpp"
#include <fstream>
#include <algorithm>
#include <chrono>
#include <iostream>
#include <memory>
#include <stdexcept>
#include <zstd.h>
using namespace scarlett;
namespace {
void require(bool ok,const char* msg){if(!ok)throw std::runtime_error(msg);}
stream::Result wrap(std::vector<std::uint8_t> data){auto hash=stream::fnv1a64(data);return {stream::Status::Ok,std::move(data),hash};}
stream::Result encode(const std::vector<std::uint8_t>& source,bool size=true){
    std::vector<std::uint8_t> compressed(ZSTD_compressBound(source.size()));
    std::unique_ptr<ZSTD_CCtx,decltype(&ZSTD_freeCCtx)> ctx(ZSTD_createCCtx(),ZSTD_freeCCtx);
    require(bool(ctx),"context");
    require(!ZSTD_isError(ZSTD_CCtx_setParameter(ctx.get(),ZSTD_c_contentSizeFlag,size?1:0)),"content size flag");
    require(!ZSTD_isError(ZSTD_CCtx_setParameter(ctx.get(),ZSTD_c_checksumFlag,1)),"checksum flag");
    const auto n=ZSTD_compress2(ctx.get(),compressed.data(),compressed.size(),source.data(),source.size());
    require(!ZSTD_isError(n),"compression");compressed.resize(n);return wrap(std::move(compressed));
}
void rejected(const assetdecode::Decoded& d,assetdecode::Status status){require(d.status==status&&d.bytes.empty(),"failure status or exposed output");}
void run(){
    using assetdecode::Status;using assetdecode::zstd_frame;
    std::vector<std::uint8_t> source(1024u*1024u);
    for(std::size_t i=0;i<source.size();++i)source[i]=static_cast<std::uint8_t>((i*17u+i/4096u)%251u);
    auto in=encode(source);
    auto actual=zstd_frame(in,source.size());require(actual.status==Status::Ready&&actual.bytes==source,"known size round trip");
    auto unknown=encode(source,false);require(ZSTD_getFrameContentSize(unknown.bytes.data(),unknown.bytes.size())==ZSTD_CONTENTSIZE_UNKNOWN,"unknown fixture");
    actual=zstd_frame(unknown,source.size());require(actual.status==Status::Ready&&actual.bytes==source,"unknown size round trip");
    rejected(zstd_frame(in,source.size()-1),Status::SizeMismatch);
    rejected(zstd_frame(unknown,source.size()-1),Status::SizeMismatch);
    rejected(zstd_frame(unknown,source.size()+1),Status::SizeMismatch);
    rejected(zstd_frame(in,source.size(),{source.size()-1,23}),Status::OutputBudgetExceeded);
    rejected(zstd_frame(in,source.size(),{0,23}),Status::InvalidLimits);
    rejected(zstd_frame(in,source.size(),{source.size(),9}),Status::InvalidLimits);
    rejected(zstd_frame(in,source.size(),{source.size(),10}),Status::DecodeFailed);
    auto corrupt=in.bytes;corrupt.back()^=0x80;
    rejected(zstd_frame(wrap(corrupt),source.size()),Status::DecodeFailed);
    corrupt=in.bytes;corrupt.pop_back();rejected(zstd_frame(wrap(corrupt),source.size()),Status::DecodeFailed);
    corrupt=in.bytes;corrupt.push_back(0);rejected(zstd_frame(wrap(corrupt),source.size()),Status::InvalidInput);
    corrupt=in.bytes;corrupt.insert(corrupt.end(),in.bytes.begin(),in.bytes.end());
    rejected(zstd_frame(wrap(corrupt),source.size()),Status::InvalidInput);
    rejected(zstd_frame(wrap({0x50,0x2a,0x4d,0x18,0,0,0,0}),0),Status::InvalidInput);
    rejected(zstd_frame({stream::Status::FileError,{},0},0),Status::ReadFailed);
    auto bad_hash=in;bad_hash.checksum^=1;rejected(zstd_frame(bad_hash,source.size()),Status::InputChecksumMismatch);
    auto token=std::make_shared<std::atomic_bool>(true);rejected(zstd_frame(in,source.size(),{},token),Status::Cancelled);
    actual=zstd_frame(encode({}),0);require(actual.status==Status::Ready&&actual.bytes.empty(),"empty frame");
    // Exercise actual file I/O, coalesced cache and decoder on original bytes.
    const auto dir=std::filesystem::temp_directory_path()/("nativex-decode-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));
    require(std::filesystem::create_directory(dir),"temp collision");
    struct Cleanup {std::filesystem::path p;~Cleanup(){std::error_code ec;std::filesystem::remove_all(p,ec);}} cleanup{dir};
    const auto file=dir/"source.zst";
    {std::ofstream f(file,std::ios::binary);f.write(reinterpret_cast<const char*>(in.bytes.data()),static_cast<std::streamsize>(in.bytes.size()));require(bool(f),"fixture write");}
    stream::Reader backend(2,8,4096);
    stream::CoalescedReader reader(backend,4096,4,4,4096);
    auto compressed=reader.read({"source",1,0,in.bytes.size()},file);
    require(compressed->status==stream::Status::Ok,"read compressed input");
    actual=zstd_frame(*compressed,source.size());require(actual.status==Status::Ready&&actual.bytes==source,"read-to-decode mismatch");
    require(reader.read({"source",1,0,in.bytes.size()},file)==compressed&&reader.stats().leader_reads==1,"cache reuse");
    std::atomic<unsigned> errors{0};std::vector<std::thread> workers;
    for(unsigned t=0;t<4;++t)workers.emplace_back([&]{for(unsigned i=0;i<32;++i){auto r=zstd_frame(in,source.size());if(r.status!=Status::Ready||r.bytes!=source)++errors;}});
    for(auto& t:workers)t.join();
    require(errors==0,"parallel decode mismatch");
    std::cout<<"{\"zstd_version\":\""<<ZSTD_versionString()<<"\",\"input_bytes\":"<<in.bytes.size()<<",\"output_bytes\":"<<source.size()<<",\"parallel_decodes\":128,\"errors\":"<<errors<<"}\n";
}
}
int main(){try{run();return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
